/**
 * Blog SEO helpers shared by the React pages and the build-time static page
 * generator (scripts/generate-social-pages.mjs), so crawlers that do not run
 * JavaScript receive exactly the same structured data. Plain JS only — no
 * JSON/asset imports — so Node can load it directly.
 */

export const SITE_URL = 'https://www.hiranilawfirm.com'
export const OG_IMAGE = { width: 1200, height: 630, type: 'image/jpeg' }
export const ATTORNEY_PATH = '/about/sehar-hirani'

/** Branded share image generated by `npm run og:blog`. */
export const ogImagePath = (slug) => `/og/blog/${slug}.jpg`

/** Publish dates are stored as YYYY-MM-DD; expose them in Houston time. */
export const isoDate = (date) => `${date}T09:00:00-05:00`

export const stripMarkup = (text) =>
  text.replace(/\*\*(.+?)\*\*|\[(.+?)\]\((\/[^)\s]*)\)/g, (_, bold, label) => bold || label)

export function postText(post) {
  return [
    ...post.intro,
    ...post.sections.flatMap((s) => [s.heading, ...s.blocks.flatMap((b) => b.list || [b.text])]),
    post.cta.title,
    ...post.cta.paragraphs,
  ]
    .map(stripMarkup)
    .join(' ')
}

const orgId = `${SITE_URL}/#organization`
const authorId = `${SITE_URL}${ATTORNEY_PATH}#person`
const blogId = `${SITE_URL}/blog#blog`

function organization(business) {
  return {
    '@type': 'LegalService',
    '@id': orgId,
    name: business.name,
    url: SITE_URL,
    telephone: business.phone,
    email: business.email,
    logo: { '@type': 'ImageObject', url: `${SITE_URL}/favicon.png`, width: 256, height: 256 },
    image: `${SITE_URL}/og-image.png`,
    areaServed: business.areasServed.map((name) => ({ '@type': 'Place', name: `${name}, TX` })),
    sameAs: Object.values(business.social),
  }
}

function author(business) {
  return {
    '@type': 'Person',
    '@id': authorId,
    name: business.attorney,
    url: `${SITE_URL}${ATTORNEY_PATH}`,
    jobTitle: 'Family Law & Personal Injury Attorney',
    worksFor: { '@id': orgId },
    sameAs: [business.social.linkedin],
  }
}

/**
 * JSON-LD @graph for a blog post: WebPage, BlogPosting, FAQPage,
 * BreadcrumbList, author and publisher, linked by @id.
 * `related` = [{ title, to }] practice-area pages the article supports.
 */
export function postSchema({ post, business, related = [] }) {
  const url = `${SITE_URL}/blog/${post.slug}`
  const image = {
    '@type': 'ImageObject',
    '@id': `${url}#primaryimage`,
    url: `${SITE_URL}${ogImagePath(post.slug)}`,
    width: OG_IMAGE.width,
    height: OG_IMAGE.height,
    caption: post.imageAlt,
  }
  const words = postText(post).split(/\s+/).filter(Boolean).length

  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'WebPage',
        '@id': url,
        url,
        name: post.metaTitle,
        description: post.metaDescription,
        inLanguage: 'en-US',
        isPartOf: { '@type': 'WebSite', '@id': `${SITE_URL}/#website`, url: SITE_URL, name: business.name },
        primaryImageOfPage: { '@id': image['@id'] },
        breadcrumb: { '@id': `${url}#breadcrumb` },
        datePublished: isoDate(post.datePublished),
        dateModified: isoDate(post.dateModified),
      },
      image,
      {
        '@type': 'BlogPosting',
        '@id': `${url}#article`,
        mainEntityOfPage: { '@id': url },
        isPartOf: { '@id': blogId },
        headline: post.title,
        description: post.metaDescription,
        image: { '@id': image['@id'] },
        thumbnailUrl: image.url,
        datePublished: isoDate(post.datePublished),
        dateModified: isoDate(post.dateModified),
        author: { '@id': authorId },
        publisher: { '@id': orgId },
        articleSection: post.categoryLabel,
        keywords: post.keywords,
        wordCount: words,
        timeRequired: `PT${post.readMinutes}M`,
        inLanguage: 'en-US',
        about: related.map((r) => ({ '@type': 'Service', name: r.title, url: `${SITE_URL}${r.to}`, provider: { '@id': orgId } })),
      },
      {
        '@type': 'FAQPage',
        '@id': `${url}#faq`,
        mainEntity: post.faqs.map((f) => ({
          '@type': 'Question',
          name: f.q,
          acceptedAnswer: { '@type': 'Answer', text: stripMarkup(f.a) },
        })),
      },
      {
        '@type': 'BreadcrumbList',
        '@id': `${url}#breadcrumb`,
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Home', item: `${SITE_URL}/` },
          { '@type': 'ListItem', position: 2, name: 'Blog', item: `${SITE_URL}/blog` },
          { '@type': 'ListItem', position: 3, name: post.title, item: url },
        ],
      },
      author(business),
      organization(business),
    ],
  }
}

/** JSON-LD @graph for the /blog index: CollectionPage + Blog + ItemList. */
export function blogIndexSchema({ blog, business }) {
  const url = `${SITE_URL}/blog`
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'CollectionPage',
        '@id': url,
        url,
        name: blog.seo.title,
        description: blog.seo.description,
        inLanguage: 'en-US',
        isPartOf: { '@type': 'WebSite', '@id': `${SITE_URL}/#website`, url: SITE_URL, name: business.name },
        breadcrumb: { '@id': `${url}#breadcrumb` },
        mainEntity: { '@id': `${url}#posts` },
      },
      {
        '@type': 'Blog',
        '@id': blogId,
        url,
        name: `${business.shortName} Blog`,
        description: blog.seo.description,
        publisher: { '@id': orgId },
        inLanguage: 'en-US',
        blogPost: blog.posts.map((p) => ({ '@id': `${SITE_URL}/blog/${p.slug}#article` })),
      },
      {
        '@type': 'ItemList',
        '@id': `${url}#posts`,
        itemListElement: blog.posts.map((p, i) => ({
          '@type': 'ListItem',
          position: i + 1,
          item: {
            '@type': 'BlogPosting',
            '@id': `${SITE_URL}/blog/${p.slug}#article`,
            url: `${SITE_URL}/blog/${p.slug}`,
            headline: p.title,
            description: p.metaDescription,
            image: `${SITE_URL}${ogImagePath(p.slug)}`,
            datePublished: isoDate(p.datePublished),
            dateModified: isoDate(p.dateModified),
            author: { '@id': authorId },
          },
        })),
      },
      {
        '@type': 'BreadcrumbList',
        '@id': `${url}#breadcrumb`,
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Home', item: `${SITE_URL}/` },
          { '@type': 'ListItem', position: 2, name: 'Blog', item: url },
        ],
      },
      author(business),
      organization(business),
    ],
  }
}
